<style>
.nc-shell{display:grid;gap:22px;min-width:0}.nc-hero,.nc-panel,.nc-card{border:1px solid rgba(212,175,55,.2);background:linear-gradient(145deg,rgba(18,18,18,.98),rgba(8,8,8,.98));border-radius:20px;padding:22px;min-width:0}.nc-hero{display:flex;justify-content:space-between;gap:18px;align-items:flex-end}.nc-kicker{color:#d4af37;text-transform:uppercase;letter-spacing:.18em;font-size:.72rem}.nc-hero h1{font-size:clamp(1.8rem,4vw,3.3rem);margin:.3rem 0}.nc-actions{display:flex;gap:10px;flex-wrap:wrap}.nc-button{border:1px solid #d4af37;color:#090909;background:#d4af37;padding:10px 15px;border-radius:10px;font-weight:700}.nc-button--ghost{background:transparent;color:#e7cc72}.nc-filter{display:flex;gap:10px;flex-wrap:wrap}.nc-filter input,.nc-filter select,.nc-field{background:#0b0b0b;border:1px solid #3c3520;color:#fff;border-radius:10px;padding:11px}.nc-list{display:grid;gap:10px}.nc-card{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:14px}.nc-card.is-unread{border-color:#d4af37;box-shadow:inset 3px 0 #d4af37}.nc-meta{display:flex;gap:8px;flex-wrap:wrap;color:#a7a7a7;font-size:.8rem}.nc-badge{background:#30270c;color:#f2d573;border-radius:999px;padding:4px 9px}.nc-table-wrap{max-width:100%;overflow-x:auto}.nc-table{width:100%;min-width:680px;border-collapse:collapse}.nc-table th,.nc-table td{text-align:left;padding:12px;border-bottom:1px solid #28230f}.nc-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.nc-form .wide{grid-column:1/-1}.nc-empty{text-align:center;padding:50px;color:#aaa}@media(max-width:640px){.nc-hero{align-items:flex-start;flex-direction:column}.nc-card{grid-template-columns:minmax(0,1fr)}.nc-form{grid-template-columns:minmax(0,1fr)}.nc-shell,.nc-panel,.nc-hero{min-width:0}.nc-button{white-space:normal}}
</style>
